/**
 * Mock Exam engine: home screen, exam/practice sessions, results and review.
 * Question data comes from questions.js (window.EXAM_DATA), generated by scripts/build_mock_exam.py.
 * Answer options are shuffled per session and explanations stay attached to their option,
 * so answer letters in the source files never leak into the exam.
 */
(function () {
  'use strict';

  const DATA = window.EXAM_DATA;
  const QMAP = Object.fromEntries(DATA.questions.map((q) => [q.id, q]));
  const SMAP = Object.fromEntries(DATA.scenarios.map((s) => [s.id, s]));
  const LETTERS = ['A', 'B', 'C', 'D'];
  const PASS_PCT = 70;
  const DOMAINS = {
    1: { name: 'Low-code agents & enterprise data', weight: 13 },
    2: { name: 'Coding agents, MCP & skills', weight: 17 },
    3: { name: 'Custom agents with ADK', weight: 33 },
    4: { name: 'Evaluate, deploy & observe', weight: 22 },
    5: { name: 'Security & governance', weight: 15 },
  };
  const MODES = {
    full: { label: 'Full mock exam', practice: false, limitMin: 120 },
    quick: { label: 'Quick exam', practice: false, limitMin: 45, size: 20 },
    scenario: { label: 'Case study drill', practice: true },
    domain: { label: 'Domain drill', practice: true },
    mistakes: { label: 'Mistake review', practice: true },
  };

  /* ---------- utils ---------- */
  const $ = (sel, root = document) => root.querySelector(sel);
  const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

  function inline(s) {
    const codes = [];
    let out = esc(s).replace(/`([^`]+)`/g, (_, c) => { codes.push(c); return `\u0000${codes.length - 1}\u0000`; });
    out = out.replace(/\*\*([^*]+?)\*\*/g, '<strong>$1</strong>')
      .replace(/(^|[^*\w])\*([^*\s][^*]*?)\*(?!\*)/g, '$1<em>$2</em>');
    return out.replace(/\u0000(\d+)\u0000/g, (_, i) => `<code>${codes[i]}</code>`);
  }

  function md(s) {
    const lines = String(s || '').split('\n');
    let html = '';
    let list = null;
    const close = () => { if (list) { html += `</${list}>`; list = null; } };
    for (const raw of lines) {
      const line = raw.trim();
      if (!line) { close(); continue; }
      const ol = line.match(/^\d+\.\s+(.*)$/);
      const ul = line.match(/^[*-]\s+(.*)$/);
      if (ol || ul) {
        const kind = ol ? 'ol' : 'ul';
        if (list !== kind) { close(); html += `<${kind}>`; list = kind; }
        html += `<li>${inline((ol || ul)[1])}</li>`;
      } else {
        close();
        html += `<p>${inline(line)}</p>`;
      }
    }
    close();
    return html;
  }

  function shuffle(arr) {
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  function fmtTime(sec) {
    sec = Math.max(0, Math.round(sec));
    const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
    const mm = String(m).padStart(h ? 2 : 1, '0'), ss = String(s).padStart(2, '0');
    return h ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;
  }

  const store = {
    get(k, def) { try { const v = localStorage.getItem('amx.' + k); return v == null ? def : JSON.parse(v); } catch { return def; } },
    set(k, v) { try { localStorage.setItem('amx.' + k, JSON.stringify(v)); } catch { /* storage unavailable */ } },
    del(k) { try { localStorage.removeItem('amx.' + k); } catch { /* storage unavailable */ } },
  };

  const topicOf = (q) => { const m = q.header.match(/\s[-–]\s(.+)$/); return m ? m[1] : ''; };
  /** Per-question record on this device: qid -> { n: attempts, ok: correct attempts, last: bool, at: ms }. */
  function questionStats() {
    const st = store.get('stats', {});
    const legacy = store.get('last', null); // older versions kept only the last result per question
    if (legacy) {
      Object.entries(legacy).forEach(([id, ok]) => { if (!st[id]) st[id] = { n: 1, ok: ok ? 1 : 0, last: ok, at: 0 }; });
      store.set('stats', st);
      store.del('last');
    }
    return st;
  }
  const lastResults = () => Object.fromEntries(Object.entries(questionStats()).map(([id, r]) => [id, r.last])); // qid -> last attempt correct?
  const mistakeIds = () => Object.entries(lastResults()).filter(([id, ok]) => !ok && QMAP[id]).map(([id]) => id);

  function recordOutcome(id, ok) {
    const st = questionStats();
    const r = st[id] || { n: 0, ok: 0 };
    st[id] = { n: r.n + 1, ok: r.ok + (ok ? 1 : 0), last: ok, at: Date.now() };
    store.set('stats', st);
  }

  function recordChip(id) {
    const r = questionStats()[id];
    if (!r) return '<span class="chip">First attempt</span>';
    return `<span class="chip ${r.last ? 'chip-good' : 'chip-bad'}" title="Your attempts at this question on this device">Your record: ${r.ok}/${r.n} correct</span>`;
  }

  /* ---------- narrator ---------- */
  /**
   * Plays pre-rendered clips from audio/ (see scripts/tts_mock_exam.py and audio/manifest.js).
   * Options are shuffled per session, so a question is a playlist of clips in on-screen order.
   * Buttons are re-rendered often, so playback state is tracked by id and re-applied by sync().
   */
  const Narrator = (() => {
    const clips = window.EXAM_AUDIO?.clips || {};
    const enabled = Object.keys(clips).length > 0;
    const RATES = [1, 1.25, 1.5, 0.85];
    const audio = new Audio();
    audio.preload = 'auto';
    let queue = [], pos = 0, current = null, lastId = null, rate = store.get('rate', 1);

    const has = (key) => !!clips[key];
    const PLAY = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 4.5v15l13-7.5Z"/></svg>';
    const PAUSE = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 4h4.5v16H6zM13.5 4H18v16h-4.5z"/></svg>';

    function button(id, label, data) {
      if (!enabled) return '';
      const attrs = Object.entries(data).map(([k, v]) => `data-${k}="${esc(v)}"`).join(' ');
      return `<button type="button" class="btn btn-ghost btn-listen" data-say-id="${esc(id)}" data-label="${esc(label)}" ${attrs} aria-pressed="false">${PLAY}<span>${esc(label)}</span></button>`;
    }
    const rateButton = () => (enabled ? `<button type="button" class="btn btn-ghost btn-rate" title="Narration speed">${rate}×</button>` : '');

    function playlist(b) {
      const { say, qid, order, sid } = b.dataset;
      if (say === 'sc') return [{ key: `sc${sid}` }];
      const q = QMAP[qid];
      const keys = order.split('');
      if (say === 'q') {
        return [{ key: qid }, ...keys.flatMap((k, i) => [{ key: `lbl-${LETTERS[i]}`, qid, hl: k }, { key: `${qid}-o${k}`, qid, hl: k }])];
      }
      // 'x': explanations, correct answer first, then the rest in on-screen order
      const ranked = [q.answer, ...keys.filter((k) => k !== q.answer)];
      return ranked.flatMap((k) => [
        { key: `lbl-${LETTERS[keys.indexOf(k)]}`, qid, hl: k },
        { key: k === q.answer ? 'lbl-ok' : 'lbl-bad', qid, hl: k },
        { key: `${qid}-w${k}`, qid, hl: k },
      ]);
    }

    function sync() {
      const it = current && queue[pos];
      $$('.btn-listen').forEach((b) => {
        const on = b.dataset.sayId === current && !audio.paused;
        b.setAttribute('aria-pressed', String(on));
        b.innerHTML = `${on ? PAUSE : PLAY}<span>${esc(b.dataset.label)}</span>`;
      });
      $$('.btn-rate').forEach((b) => { b.textContent = `${rate}×`; });
      $$('.option.speaking').forEach((o) => o.classList.remove('speaking'));
      if (it?.hl) $$(`[data-qscope="${it.qid}"] .option[data-key="${it.hl}"]`).forEach((o) => o.classList.add('speaking'));
    }

    function playAt(i) {
      pos = i;
      while (pos < queue.length && !has(queue[pos].key)) pos++;
      if (pos >= queue.length) { stop(); return; }
      const key = queue[pos].key;
      audio.src = `audio/${key}.mp3?v=${clips[key].h}`;
      audio.playbackRate = rate;
      audio.play().then(sync, () => stop());
      sync();
    }
    audio.addEventListener('ended', () => playAt(pos + 1));
    audio.addEventListener('error', () => { if (current) playAt(pos + 1); });

    function toggle(b) {
      if (b.dataset.sayId === current) {
        if (audio.paused) audio.play().then(sync, () => stop()); else { audio.pause(); sync(); }
        return;
      }
      stop();
      current = lastId = b.dataset.sayId;
      queue = playlist(b);
      playAt(0);
    }

    /** Stops playback; with a prefix, only if the current playlist id starts with it. */
    function stop(prefix) {
      if (!current || (prefix && !current.startsWith(prefix))) return;
      audio.pause();
      audio.removeAttribute('src');
      current = null; queue = []; pos = 0;
      sync();
    }

    function cycleRate() {
      rate = RATES[(RATES.indexOf(rate) + 1) % RATES.length];
      store.set('rate', rate);
      audio.playbackRate = rate;
      sync();
    }

    function clickListen(sayId) {
      const b = $(`.btn-listen[data-say-id="${sayId}"]`);
      if (b) toggle(b);
    }

    document.addEventListener('click', (e) => {
      const b = e.target.closest('.btn-listen');
      if (b) { e.preventDefault(); toggle(b); return; }
      if (e.target.closest('.btn-rate')) { e.preventDefault(); cycleRate(); }
    });

    /** Restarts the playing (or last played) narration from the top; falls back to `fallbackId`. */
    function replay(fallbackId) {
      const id = [current, lastId].find((x) => x && $(`.btn-listen[data-say-id="${x}"]`)) || fallbackId;
      const b = $(`.btn-listen[data-say-id="${id}"]`);
      if (!b) return;
      stop();
      toggle(b);
    }

    return { enabled, button, rateButton, stop, sync, clickListen, replay };
  })();

  /* ---------- theme ---------- */
  function applyTheme(t) {
    if (t) document.documentElement.setAttribute('data-theme', t);
    else document.documentElement.removeAttribute('data-theme');
  }
  applyTheme(store.get('theme', null));
  $('#theme-toggle').addEventListener('click', () => {
    const cur = document.documentElement.getAttribute('data-theme') ||
      (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
    const next = cur === 'dark' ? 'light' : 'dark';
    applyTheme(next);
    store.set('theme', next);
  });

  /* ---------- views ---------- */
  function show(view) {
    Narrator.stop();
    ['home', 'exam', 'results'].forEach((v) => { $('#view-' + v).hidden = v !== view; });
    window.scrollTo({ top: 0 });
  }

  /* ================= HOME ================= */
  const ICON = {
    exam: '<svg viewBox="0 0 24 24"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/></svg>',
    bolt: '<svg viewBox="0 0 24 24"><path d="M13 2 4 14h7l-1 8 9-12h-7Z"/></svg>',
    map: '<svg viewBox="0 0 24 24"><rect x="3" y="4" width="7" height="7" rx="1.5"/><rect x="14" y="4" width="7" height="7" rx="1.5"/><rect x="8.5" y="14" width="7" height="7" rx="1.5"/><path d="M6.5 11v1.5h11V11M12 12.5V14"/></svg>',
    layers: '<svg viewBox="0 0 24 24"><path d="m12 3 9 5-9 5-9-5Z"/><path d="m3 13 9 5 9-5"/></svg>',
    retry: '<svg viewBox="0 0 24 24"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5"/></svg>',
  };

  function renderHome() {
    const heroId = 1 + Math.floor(Math.random() * DATA.scenarios.length);
    $('#hero-art').innerHTML = ExamDiagrams.render(heroId) +
      `<p class="muted small" style="margin:8px 6px 2px">Case study ${heroId}: ${esc(SMAP[heroId].title)}</p>`;
    $('#hero-stats').innerHTML = [
      [DATA.questions.length, 'questions'], [DATA.scenarios.length, 'case studies'], [5, 'domains'], [MODES.full.limitMin, 'minutes'],
    ].map(([n, l]) => `<div><b>${n}</b><span>${l}</span></div>`).join('');

    // resume banner
    const saved = store.get('session', null);
    const banner = $('#resume-banner');
    if (saved && !saved.done && saved.items && saved.items.every((it) => QMAP[it.id])) {
      const answered = Object.keys(saved.answers).length;
      banner.hidden = false;
      banner.innerHTML = `<div><strong>Unfinished session:</strong> ${esc(saved.title)} · ${answered}/${saved.items.length} answered · ${fmtTime(saved.elapsedMs / 1000)} elapsed</div>
        <div class="banner-actions"><button class="btn btn-ghost" data-act="discard">Discard</button><button class="btn btn-primary" data-act="resume">Resume</button></div>`;
      banner.onclick = (e) => {
        const act = e.target.closest('button')?.dataset.act;
        if (act === 'resume') { S = saved; enterExam(); }
        if (act === 'discard') { store.del('session'); renderHome(); }
      };
    } else {
      banner.hidden = true;
    }

    // modes
    const nMist = mistakeIds().length;
    $('#modes').innerHTML = `
      <button class="mode-card" data-mode="full">
        <span class="mode-icon">${ICON.exam}</span>
        <h3>Full mock exam</h3>
        <p>All 50 questions grouped by case study. Timed, no hints until you submit.</p>
        <span class="mode-meta"><span class="chip chip-accent">50 Q</span><span class="chip">120 min</span><span class="chip chip-ask">Personal best</span></span>
      </button>
      <button class="mode-card" data-mode="quick">
        <span class="mode-icon">${ICON.bolt}</span>
        <h3>Quick exam</h3>
        <p>20 random questions from every domain. A good warm-up for a coffee break.</p>
        <span class="mode-meta"><span class="chip chip-accent">20 Q</span><span class="chip">45 min</span></span>
      </button>
      <button class="mode-card" data-mode="scenario-pick">
        <span class="mode-icon">${ICON.map}</span>
        <h3>Case study drill</h3>
        <p>Pick one case study and practise its 5 questions, with feedback after each answer.</p>
        <span class="mode-meta"><span class="chip">Practice</span><span class="chip">instant feedback</span></span>
      </button>
      <div class="mode-card" role="group" aria-label="Domain drill">
        <span class="mode-icon">${ICON.layers}</span>
        <h3>Domain drill</h3>
        <p>Every question that covers one exam domain.</p>
        <span class="mode-meta">${Object.keys(DOMAINS).map((d) => `<button class="chip chip-accent filter" data-mode="domain" data-arg="${d}" title="${esc(DOMAINS[d].name)}">D${d}</button>`).join('')}</span>
      </div>
      <button class="mode-card" data-mode="mistakes" ${nMist ? '' : 'disabled'}>
        <span class="mode-icon">${ICON.retry}</span>
        <h3>Review mistakes</h3>
        <p>${nMist ? `Retry the ${nMist} question${nMist > 1 ? 's' : ''} you got wrong last time.` : 'No mistakes recorded yet. Missed questions will show up here.'}</p>
        <span class="mode-meta"><span class="chip ${nMist ? 'chip-bad' : ''}">${nMist} to review</span></span>
      </button>`;
    $('#modes').onclick = (e) => {
      const b = e.target.closest('[data-mode]');
      if (!b || b.disabled) return;
      if (b.dataset.mode === 'scenario-pick') { $('#scenario-grid').scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
      startSession(b.dataset.mode, b.dataset.arg ? Number(b.dataset.arg) : undefined);
    };

    // scenario cards
    const last = lastResults();
    $('#scenario-grid').innerHTML = DATA.scenarios.map((sc) => {
      const qs = DATA.questions.filter((q) => q.scenario === sc.id);
      const ok = qs.filter((q) => last[q.id] === true).length;
      const seen = qs.filter((q) => q.id in last).length;
      return `<button class="scenario-card" data-sid="${sc.id}">
        <div class="scenario-thumb">${ExamDiagrams.render(sc.id)}</div>
        <div class="scenario-body">
          <span class="scenario-num">Case study ${sc.id}</span>
          <h3>${esc(sc.title)}</h3>
          <div class="scenario-foot">
            <span class="mode-meta">${sc.domains.map((d) => `<span class="chip">D${d}</span>`).join('')}</span>
            <span class="mastery">${seen ? `${ok}/${qs.length} correct` : `${qs.length} questions`}</span>
          </div>
        </div>
      </button>`;
    }).join('');
    $('#scenario-grid').onclick = (e) => {
      const c = e.target.closest('[data-sid]');
      if (c) startSession('scenario', Number(c.dataset.sid));
    };

    // domain weights
    $('#domain-weights').innerHTML = Object.entries(DOMAINS).map(([d, info]) => {
      const n = DATA.questions.filter((q) => q.domains.includes(Number(d))).length;
      return `<div class="dw-row"><b>D${d} · ${esc(info.name)}</b><span>${info.weight}% · ${n} Q</span>
        <div class="meter"><i style="width:${(info.weight / 33) * 100}%"></i></div></div>`;
    }).join('');

    // history, with the change against the previous attempt in the same mode
    const hist = store.get('history', []);
    $('#history').innerHTML = hist.length
      ? hist.slice(0, 8).map((h, i) => {
        const prev = hist.slice(i + 1).find((p) => p.mode === h.mode && p.arg === h.arg);
        const d = prev ? h.pct - prev.pct : null;
        const delta = d === null ? '' : `<span class="delta ${d > 0 ? 'up' : d < 0 ? 'down' : ''}">${d > 0 ? '▲' : d < 0 ? '▼' : '='}${d ? Math.abs(d) : ''}</span>`;
        return `<div class="history-row"><span>${esc(h.title)}<br><span class="muted small">${new Date(h.date).toLocaleDateString()} · ${fmtTime(h.elapsedSec)}</span></span>
          <span class="history-score">${delta}<span class="chip ${h.pct >= PASS_PCT ? 'chip-good' : 'chip-bad'}">${h.correct}/${h.total} · ${h.pct}%</span></span></div>`;
      }).join('')
      : '<p class="muted small" style="margin:0">Your attempts on this device will appear here.</p>';

    renderProgress();
    show('home');
  }

  const bestScore = (hist, mode) => hist.filter((h) => h.mode === mode).reduce((m, h) => Math.max(m, h.pct), -1);

  function renderProgress() {
    const st = questionStats();
    const ids = DATA.questions.map((q) => q.id);
    const seen = ids.filter((id) => st[id]);
    const attempts = seen.reduce((n, id) => n + st[id].n, 0);
    const correct = seen.reduce((n, id) => n + st[id].ok, 0);
    const mastered = ids.filter((id) => st[id]?.last).length;
    const best = bestScore(store.get('history', []), 'full');
    const kpi = (v, l) => `<div><b>${v}</b><span>${l}</span></div>`;
    const el = $('#my-progress');
    if (!seen.length) {
      el.innerHTML = '<p class="muted small" style="margin:0">Answer a few questions and your progress shows up here: accuracy, mastered questions and weak domains.</p>';
      return;
    }
    const byDomain = Object.keys(DOMAINS).map((d) => {
      const qs = DATA.questions.filter((q) => q.domains.includes(Number(d)));
      return { label: `D${d} · ${esc(DOMAINS[d].name)}`, ok: qs.filter((q) => st[q.id]?.last).length, n: qs.length };
    });
    el.innerHTML = `
      <div class="progress-kpis">
        ${kpi(`${seen.length}/${ids.length}`, 'seen')}
        ${kpi(`${mastered}`, 'mastered')}
        ${kpi(`${Math.round((correct / attempts) * 100)}%`, 'accuracy')}
        ${kpi(best >= 0 ? `${best}%` : '—', 'best full exam')}
      </div>
      <p class="muted small">Mastered = correct on your latest attempt. Accuracy is across all ${attempts} attempt${attempts > 1 ? 's' : ''}.</p>
      ${breakdownRows(byDomain)}
      <button class="btn btn-ghost btn-small" id="btn-reset" type="button">Reset my progress</button>`;
    $('#btn-reset').onclick = () => {
      if (!confirm('Delete your question history, attempts and mistakes on this device?')) return;
      ['stats', 'last', 'history', 'session'].forEach((k) => store.del(k));
      renderHome();
    };
  }

  /* ================= SESSION ================= */
  let S = null;
  let timerId = null;
  let lastTick = 0;
  let panelScenario = null;

  function groupByScenario(ids, shuffleOrder) {
    const groups = new Map();
    ids.forEach((id) => {
      const s = QMAP[id].scenario;
      if (!groups.has(s)) groups.set(s, []);
      groups.get(s).push(id);
    });
    let keys = [...groups.keys()];
    keys = shuffleOrder ? shuffle(keys) : keys.sort((a, b) => a - b);
    return keys.flatMap((k) => (shuffleOrder ? shuffle(groups.get(k)) : groups.get(k)));
  }

  function startSession(mode, arg) {
    const all = DATA.questions.map((q) => q.id);
    let ids, title;
    switch (mode) {
      case 'full': ids = groupByScenario(all, true); title = MODES.full.label; break;
      case 'quick': ids = groupByScenario(shuffle(all).slice(0, MODES.quick.size), true); title = MODES.quick.label; break;
      case 'scenario': ids = DATA.questions.filter((q) => q.scenario === arg).map((q) => q.id); title = `Case study ${arg}: ${SMAP[arg].title}`; break;
      case 'domain': ids = groupByScenario(DATA.questions.filter((q) => q.domains.includes(arg)).map((q) => q.id), false); title = `Domain ${arg}: ${DOMAINS[arg].name}`; break;
      case 'mistakes': ids = groupByScenario(mistakeIds(), false); title = MODES.mistakes.label; break;
      default: return;
    }
    if (!ids.length) return;
    const m = MODES[mode];
    S = {
      v: 1, mode, arg, title, practice: m.practice,
      limitSec: m.limitMin ? m.limitMin * 60 : 0,
      items: ids.map((id) => ({ id, order: shuffle(LETTERS) })),
      idx: 0, answers: {}, checked: {}, flags: [], elapsedMs: 0, streak: 0, bestStreak: 0, done: false,
    };
    save();
    enterExam();
  }

  function save() { if (S && !S.done) store.set('session', S); }

  function enterExam() {
    panelScenario = null;
    $('#mode-pill').textContent = MODES[S.mode].label;
    $('#btn-finish').textContent = S.practice ? 'End' : 'Finish';
    $('#streak').hidden = !S.practice;
    $('#navigator').hidden = true;
    show('exam');
    renderQuestion();
    startTimer();
  }

  function startTimer() {
    stopTimer();
    lastTick = Date.now();
    updateTimer();
    let n = 0;
    timerId = setInterval(() => {
      const now = Date.now();
      S.elapsedMs += now - lastTick;
      lastTick = now;
      updateTimer();
      if (S.limitSec && S.elapsedMs / 1000 >= S.limitSec) { finish(true); return; }
      if (++n % 5 === 0) save();
    }, 1000);
  }

  function stopTimer() {
    if (timerId) {
      clearInterval(timerId);
      timerId = null;
      if (S && lastTick) S.elapsedMs += Date.now() - lastTick;
      lastTick = 0;
    }
  }

  function updateTimer() {
    const el = $('#timer');
    const elapsed = S.elapsedMs / 1000;
    if (S.limitSec) {
      const left = S.limitSec - elapsed;
      el.textContent = fmtTime(left);
      el.title = 'Time remaining';
      el.classList.toggle('low', left < 300);
    } else {
      el.textContent = fmtTime(elapsed);
      el.title = 'Time elapsed';
      el.classList.remove('low');
    }
  }

  document.addEventListener('visibilitychange', () => { if (document.hidden) save(); });
  window.addEventListener('pagehide', () => { if (timerId) { S.elapsedMs += Date.now() - lastTick; lastTick = Date.now(); } save(); });

  /* ---------- question rendering ---------- */
  function isCorrect(id, key) { return key === QMAP[id].answer; }

  /**
   * Renders the stem and options of a question.
   * opts: { selected, revealed, disabled }
   */
  function questionHTML(q, order, opts) {
    const { selected, revealed, disabled } = opts;
    const labelled = q.goal || q.constraints.length;
    let h = `<div class="q-block">${labelled ? '<span class="q-label">Context:</span> ' : ''}${inline(q.context)}</div>`;
    if (q.goal) h += `<div class="q-block"><span class="q-label">Goal:</span> ${inline(q.goal)}</div>`;
    if (q.constraints.length) {
      h += `<div class="q-block"><span class="q-label">Constraints:</span></div><ul class="q-constraints">${q.constraints.map((c) => `<li>${inline(c)}</li>`).join('')}</ul>`;
    }
    h += `<p class="q-prompt">${inline(q.prompt)}</p><ul class="options" role="radiogroup" aria-label="Answer options">`;
    order.forEach((key, i) => {
      const cls = ['option'];
      if (selected === key) cls.push('selected');
      if (revealed) {
        if (key === q.answer) cls.push('correct');
        else if (selected === key) cls.push('wrong');
        else cls.push('dim');
      }
      const why = revealed
        ? `<div class="why"><div class="why-head">${key === q.answer ? 'Why it’s correct' : 'Why it fails'}</div>${md(q.why[key])}</div>`
        : '';
      h += `<li><button type="button" class="${cls.join(' ')}" data-key="${key}" role="radio" aria-checked="${selected === key}" ${disabled ? 'disabled' : ''}>
        <span class="option-letter">${LETTERS[i]}</span><span class="option-text">${md(q.options[key])}</span>${why}</button></li>`;
    });
    h += '</ul>';
    return h;
  }

  function audioRow(qid, order, revealed) {
    if (!Narrator.enabled) return '';
    const data = { qid, order: order.join('') };
    return `<span class="audio-row">${Narrator.button(`q:${qid}`, 'Listen', { say: 'q', ...data })}${
      revealed ? Narrator.button(`x:${qid}`, 'Explanations', { say: 'x', ...data }) : ''}${Narrator.rateButton()}</span>`;
  }

  function scenarioPanelHTML(sc, index, count) {
    return `<details class="scenario-panel" open>
      <summary><div class="sp-head"><span class="scenario-num">Case study ${sc.id}${index ? ` · part ${index} of ${count}` : ''}</span><span class="sp-toggle">show / hide</span></div>
        <h2 class="sp-title">${esc(sc.title)}</h2></summary>
      <button type="button" class="diagram-btn" data-sid="${sc.id}" aria-label="Enlarge diagram">${ExamDiagrams.render(sc.id)}</button>
      <div class="sp-section">
        ${Narrator.enabled ? `<div class="audio-row">${Narrator.button(`sc:${sc.id}`, 'Listen to brief', { say: 'sc', sid: sc.id })}${Narrator.rateButton()}</div>` : ''}
        <h4>Setup</h4><p>${inline(sc.context)}</p>
        <h4>Goal</h4><p>${inline(sc.goal)}</p>
        <h4>Constraints</h4><ul>${sc.constraints.map((c) => `<li>${inline(c)}</li>`).join('')}</ul>
      </div>
    </details>`;
  }

  function scenarioOrder() {
    const seen = [];
    S.items.forEach((it) => { const s = QMAP[it.id].scenario; if (!seen.includes(s)) seen.push(s); });
    return seen;
  }

  function renderQuestion() {
    const item = S.items[S.idx];
    const q = QMAP[item.id];
    const sc = SMAP[q.scenario];
    const sOrder = scenarioOrder();
    const selected = S.answers[item.id];
    const revealed = S.practice && !!S.checked[item.id];
    const flagged = S.flags.includes(item.id);
    const isLast = S.idx === S.items.length - 1;
    const firstOfScenario = S.idx === 0 || QMAP[S.items[S.idx - 1].id].scenario !== q.scenario;

    if (panelScenario !== sc.id) {
      Narrator.stop('sc:');
      $('#scenario-slot').innerHTML = scenarioPanelHTML(sc, sOrder.length > 1 ? sOrder.indexOf(sc.id) + 1 : 0, sOrder.length);
      panelScenario = sc.id;
    }

    const nInScenario = S.items.filter((it) => QMAP[it.id].scenario === q.scenario);
    const posInScenario = nInScenario.findIndex((it) => it.id === item.id) + 1;

    let h = '';
    if (firstOfScenario && sOrder.length > 1 && !selected) {
      h += `<div class="scenario-intro"><span class="ask-inline">i</span><span>New case study: <strong>${esc(sc.title)}</strong>. Read the brief and diagram first.</span></div>`;
    }
    h += `<div class="q-meta">
        <span class="chip chip-accent">Case study ${sc.id} · Q${posInScenario}/${nInScenario.length}</span>
        ${q.domains.map((d) => `<span class="chip" title="${esc(DOMAINS[d].name)}">Domain ${d}</span>`).join('')}
        ${flagged ? '<span class="chip chip-ask">Flagged</span>' : ''}
        ${audioRow(item.id, item.order, revealed)}
      </div>`;
    if (revealed) h += `<div class="q-topic">${topicOf(q) ? `<span>Topic: ${inline(topicOf(q))}</span>` : ''}${recordChip(item.id)}</div>`;
    h += questionHTML(q, item.order, { selected, revealed, disabled: revealed });

    if (revealed) {
      const ok = isCorrect(item.id, selected);
      h += `<div class="verdict ${ok ? 'ok' : 'bad'}">${ok ? '✓ Correct.' : `✕ Not quite. The answer is ${LETTERS[item.order.indexOf(q.answer)]}.`}${ok && S.streak > 1 ? ` That's ${S.streak} in a row.` : ''}</div>`;
    }

    // Enter always triggers the primary button; Next stays available to skip a practice question.
    const nextBtn = (cls) => (isLast
      ? `<button class="btn ${cls}" data-act="finish">${S.practice ? 'See summary' : 'Review & submit'}</button>`
      : `<button class="btn ${cls}" data-act="next">Next →</button>`);
    let primary;
    if (S.practice && !revealed) primary = `<button class="btn btn-primary" data-act="check" ${selected ? '' : 'disabled'}>Submit answer</button>${nextBtn('btn-ghost')}`;
    else primary = nextBtn('btn-primary');

    h += `<div class="q-foot">
        <button class="btn btn-ghost" data-act="prev" ${S.idx === 0 ? 'disabled' : ''}>← Previous</button>
        <div class="q-foot-right">
          <button class="btn btn-ghost btn-flag" data-act="flag" aria-pressed="${flagged}">${flagged ? 'Flagged' : 'Flag for review'}</button>
          ${primary}
        </div>
      </div>
      <p class="kbd-hint"><kbd>1</kbd>–<kbd>4</kbd> select · <kbd>Enter</kbd> ${S.practice ? (revealed ? 'next' : 'submit') : 'next'} · <kbd>N</kbd> / <kbd>→</kbd> next · <kbd>←</kbd> previous · <kbd>F</kbd> flag${Narrator.enabled ? ` · <kbd>L</kbd> listen${revealed ? ' · <kbd>E</kbd> explanations' : ''} · <kbd>R</kbd> replay audio` : ''}</p>`;

    const card = $('#question-card');
    card.innerHTML = h;
    card.dataset.qscope = item.id;
    Narrator.sync();

    // top bar
    const answered = Object.keys(S.answers).length;
    $('#progress-text').textContent = `Question ${S.idx + 1} of ${S.items.length} · ${answered} answered`;
    $('#progress-fill').style.width = `${(answered / S.items.length) * 100}%`;
    $('#streak').textContent = `Streak ${S.streak} · best ${S.bestStreak}`;
    if (!$('#navigator').hidden) renderNavigator();
  }

  function select(key) {
    const id = S.items[S.idx].id;
    if (S.practice && S.checked[id]) return;
    S.answers[id] = key;
    save();
    renderQuestion();
  }

  function check() {
    const id = S.items[S.idx].id;
    if (!S.answers[id] || S.checked[id]) return;
    S.checked[id] = true;
    const ok = isCorrect(id, S.answers[id]);
    S.streak = ok ? S.streak + 1 : 0;
    S.bestStreak = Math.max(S.bestStreak, S.streak);
    recordOutcome(id, ok);
    save();
    renderQuestion();
    $('.verdict')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  function go(i) {
    if (i < 0 || i >= S.items.length) return;
    Narrator.stop('q:');
    Narrator.stop('x:');
    S.idx = i;
    save();
    renderQuestion();
    const card = $('#question-card');
    if (card.getBoundingClientRect().top < 0) window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  function toggleFlag() {
    const id = S.items[S.idx].id;
    S.flags = S.flags.includes(id) ? S.flags.filter((f) => f !== id) : [...S.flags, id];
    save();
    renderQuestion();
  }

  $('#question-card').addEventListener('click', (e) => {
    const opt = e.target.closest('.option');
    if (opt && !opt.disabled) { select(opt.dataset.key); return; }
    const act = e.target.closest('[data-act]')?.dataset.act;
    if (act === 'prev') go(S.idx - 1);
    if (act === 'next') go(S.idx + 1);
    if (act === 'flag') toggleFlag();
    if (act === 'check') check();
    if (act === 'finish') requestFinish();
  });

  $('#scenario-slot').addEventListener('click', (e) => {
    const b = e.target.closest('.diagram-btn');
    if (!b) return;
    const sc = SMAP[Number(b.dataset.sid)];
    $('#dlg-diagram-title').textContent = `Case study ${sc.id}: ${sc.title}`;
    $('#dlg-diagram-body').innerHTML = ExamDiagrams.render(sc.id);
    $('#dlg-diagram').showModal();
  });

  /* ---------- navigator ---------- */
  function renderNavigator() {
    const groups = [];
    S.items.forEach((it, i) => {
      const sid = QMAP[it.id].scenario;
      if (!groups.length || groups[groups.length - 1].sid !== sid) groups.push({ sid, cells: [] });
      const cls = ['nav-cell'];
      if (S.answers[it.id]) cls.push('answered');
      if (S.practice && S.checked[it.id]) cls.push(isCorrect(it.id, S.answers[it.id]) ? 'good' : 'bad');
      if (S.flags.includes(it.id)) cls.push('flagged');
      if (i === S.idx) cls.push('current');
      groups[groups.length - 1].cells.push(`<button class="${cls.join(' ')}" data-i="${i}" aria-label="Question ${i + 1}">${i + 1}</button>`);
    });
    $('#navigator-grid').innerHTML = groups.map((g) =>
      `<div class="nav-group"><div class="nav-group-label">Case study ${g.sid}</div><div class="nav-cells">${g.cells.join('')}</div></div>`).join('');
  }
  $('#btn-nav').addEventListener('click', () => {
    const nav = $('#navigator');
    nav.hidden = !nav.hidden;
    if (!nav.hidden) renderNavigator();
  });
  $('#btn-nav-close').addEventListener('click', () => { $('#navigator').hidden = true; });
  $('#navigator-grid').addEventListener('click', (e) => {
    const c = e.target.closest('[data-i]');
    if (!c) return;
    $('#navigator').hidden = true;
    go(Number(c.dataset.i));
  });

  /* ---------- exit / finish ---------- */
  $('#btn-exit').addEventListener('click', () => $('#dlg-exit').showModal());
  $('#dlg-exit').addEventListener('close', () => {
    if ($('#dlg-exit').returnValue !== 'ok') return;
    stopTimer();
    save();
    S = null;
    renderHome();
  });

  $('#btn-finish').addEventListener('click', requestFinish);

  function requestFinish() {
    const unanswered = S.items.length - Object.keys(S.answers).length;
    const flagged = S.flags.length;
    const bits = [];
    if (unanswered) bits.push(`<strong>${unanswered}</strong> unanswered question${unanswered > 1 ? 's' : ''} (scored as incorrect)`);
    if (flagged) bits.push(`<strong>${flagged}</strong> flagged for review`);
    $('#dlg-finish').querySelector('h3').textContent = S.practice ? 'End this practice session?' : 'Submit your exam?';
    $('#dlg-finish-body').innerHTML = bits.length ? `You have ${bits.join(' and ')}.` : 'All questions are answered. Good luck!';
    $('#dlg-finish').showModal();
  }
  $('#dlg-finish').addEventListener('close', () => {
    if ($('#dlg-finish').returnValue === 'ok') finish(false);
  });

  function finish(timedOut) {
    stopTimer();
    S.done = true;
    store.del('session');

    const items = S.items.map((it) => ({ ...it, selected: S.answers[it.id] || null, ok: isCorrect(it.id, S.answers[it.id]) }));
    // Exams record every outcome at the end; practice already recorded checked answers.
    items.forEach((it) => { if (!S.practice || (it.selected && !S.checked[it.id])) recordOutcome(it.id, it.ok); });

    const correct = items.filter((i) => i.ok).length;
    const result = {
      mode: S.mode, arg: S.arg, title: S.title, practice: S.practice, timedOut,
      total: items.length, correct, pct: Math.round((correct / items.length) * 100),
      elapsedSec: Math.round(S.elapsedMs / 1000), items, flags: S.flags.slice(), bestStreak: S.bestStreak,
    };
    const hist = store.get('history', []);
    result.prev = hist.find((h) => h.mode === S.mode && h.arg === S.arg) || null;
    result.best = bestScore(hist, S.mode);
    hist.unshift({ date: Date.now(), title: S.title, mode: S.mode, arg: S.arg, correct, total: result.total, pct: result.pct, elapsedSec: result.elapsedSec });
    store.set('history', hist.slice(0, 50));

    S = null;
    renderResults(result);
  }

  /* ================= RESULTS ================= */
  function rankTitle(pct) {
    if (pct >= 90) return 'Principal Agentic Architect';
    if (pct >= PASS_PCT) return 'Agentic Architect';
    if (pct >= 50) return 'Agent Builder';
    return 'Prompt Tinkerer';
  }

  function breakdownRows(entries) {
    return entries.map(({ label, ok, n }) => {
      const pct = n ? Math.round((ok / n) * 100) : 0;
      const cls = pct >= PASS_PCT ? 'good' : pct >= 50 ? 'mid' : 'bad';
      return `<div class="bd-row"><span>${label}</span><span class="muted">${ok}/${n} · ${pct}%</span><div class="meter"><i class="${cls}" style="width:${Math.max(pct, 2)}%"></i></div></div>`;
    }).join('');
  }

  function renderResults(r) {
    const R = 62, C = 2 * Math.PI * R;
    const color = r.pct >= PASS_PCT ? 'var(--good)' : r.pct >= 50 ? 'var(--ask)' : 'var(--bad)';

    const byDomain = Object.keys(DOMAINS).map((d) => {
      const its = r.items.filter((it) => QMAP[it.id].domains.includes(Number(d)));
      return { label: `D${d} · ${esc(DOMAINS[d].name)}`, ok: its.filter((i) => i.ok).length, n: its.length };
    }).filter((x) => x.n);
    const scIds = [...new Set(r.items.map((it) => QMAP[it.id].scenario))].sort((a, b) => a - b);
    const byScenario = scIds.map((sid) => {
      const its = r.items.filter((it) => QMAP[it.id].scenario === sid);
      return { label: `${sid}. ${esc(SMAP[sid].title)}`, ok: its.filter((i) => i.ok).length, n: its.length };
    });

    const verdict = r.practice
      ? `Practice summary: ${esc(r.title)}`
      : r.pct >= PASS_PCT ? 'You are on track to pass. Tighten up the weak domains below.' : `Target is ${PASS_PCT}%. Work through the explanations below, then try again.`;

    const el = $('#view-results');
    el.innerHTML = `
      <div class="results-hero">
        <svg class="ring" viewBox="0 0 150 150" role="img" aria-label="Score ${r.pct}%">
          <circle class="ring-bg" cx="75" cy="75" r="${R}"/>
          <circle class="ring-fg" cx="75" cy="75" r="${R}" stroke="${color}" stroke-dasharray="${C}" stroke-dashoffset="${C}"/>
          <text x="75" y="84" font-size="32">${r.pct}%</text>
        </svg>
        <div>
          <p class="eyebrow">${esc(MODES[r.mode].label)}${r.timedOut ? ' · time expired' : ''}</p>
          <h1 class="results-title">${esc(rankTitle(r.pct))}</h1>
          <p class="results-sub">${verdict}</p>
          <div class="results-kpis">
            <div><b>${r.correct}/${r.total}</b><span>correct</span></div>
            <div><b>${fmtTime(r.elapsedSec)}</b><span>time used</span></div>
            <div><b>${r.items.filter((i) => !i.selected).length}</b><span>unanswered</span></div>
            <div><b>${r.flags.length}</b><span>flagged</span></div>
            ${r.practice ? `<div><b>${r.bestStreak}</b><span>best streak</span></div>` : ''}
            ${r.prev ? `<div><b>${r.pct - r.prev.pct > 0 ? '+' : ''}${r.pct - r.prev.pct} pts</b><span>vs last time (${r.prev.pct}%)</span></div>` : ''}
            ${r.best >= 0 ? `<div><b>${r.pct > r.best ? 'New best' : `${r.best}%`}</b><span>${r.pct > r.best ? `was ${r.best}%` : 'personal best'}</span></div>` : ''}
          </div>
        </div>
      </div>

      <div class="results-grid">
        <div class="card"><h2 class="section-title" style="margin-top:0">By domain</h2>${breakdownRows(byDomain)}</div>
        <div class="card"><h2 class="section-title" style="margin-top:0">By case study</h2>${breakdownRows(byScenario)}</div>
      </div>


      <div class="review-head">
        <h2 class="section-title">Review answers</h2>
        <div class="filters" id="review-filters">
          <button class="chip filter" data-f="all" aria-pressed="true">All ${r.total}</button>
          <button class="chip filter" data-f="wrong" aria-pressed="false">Incorrect ${r.total - r.correct}</button>
          <button class="chip filter" data-f="flagged" aria-pressed="false">Flagged ${r.flags.length}</button>
        </div>
      </div>
      <div id="review-list"></div>

      <div class="results-actions">
        <button class="btn btn-ghost" data-act="home">Home</button>
        ${r.total - r.correct ? '<button class="btn btn-ghost" data-act="mistakes">Retry my mistakes</button>' : ''}
        <button class="btn btn-primary" data-act="again">Start another ${esc(MODES[r.mode].label.toLowerCase())}</button>
      </div>`;

    show('results');
    requestAnimationFrame(() => requestAnimationFrame(() => {
      const fg = el.querySelector('.ring-fg');
      if (fg) fg.style.strokeDashoffset = String(C * (1 - r.pct / 100));
    }));

    const renderReview = (f) => {
      const list = r.items.filter((it) => f === 'all' || (f === 'wrong' && !it.ok) || (f === 'flagged' && r.flags.includes(it.id)));
      $('#review-list').innerHTML = list.length ? list.map((it) => {
        const q = QMAP[it.id];
        const n = r.items.indexOf(it) + 1;
        const mark = !it.selected ? '<span class="mark skip">–</span>' : it.ok ? '<span class="mark ok">✓</span>' : '<span class="mark bad">✕</span>';
        return `<details class="review-item">
          <summary>${mark}<span class="review-title">Q${n}. ${inline(topicOf(q) || q.prompt)}<small>Case study ${q.scenario}: ${esc(SMAP[q.scenario].title)}</small></span>
            ${r.flags.includes(it.id) ? '<span class="chip chip-ask">Flagged</span>' : '<span></span>'}</summary>
          <div class="review-body" data-qscope="${q.id}"><div class="audio-row">${recordChip(q.id)}${audioRow(q.id, it.order, true)}</div>${questionHTML(q, it.order, { selected: it.selected, revealed: true, disabled: true })}</div>
        </details>`;
      }).join('') : '<p class="muted">Nothing to show for this filter.</p>';
      Narrator.stop();
    };
    renderReview('all');
    $('#review-filters').onclick = (e) => {
      const b = e.target.closest('[data-f]');
      if (!b) return;
      $$('#review-filters .filter').forEach((x) => x.setAttribute('aria-pressed', String(x === b)));
      renderReview(b.dataset.f);
    };

    el.querySelector('.results-actions').onclick = (e) => {
      const act = e.target.closest('[data-act]')?.dataset.act;
      if (act === 'home') renderHome();
      if (act === 'mistakes') startSession('mistakes');
      if (act === 'again') startSession(r.mode, r.arg);
    };

  }

  /* ---------- keyboard ---------- */
  document.addEventListener('keydown', (e) => {
    if ($('#view-exam').hidden || !S || document.querySelector('dialog[open]')) return;
    if (e.target.matches('input, textarea') || e.metaKey || e.ctrlKey || e.altKey) return;
    const k = e.key.toLowerCase();
    const idx = ['1', '2', '3', '4'].indexOf(k) >= 0 ? Number(k) - 1 : ['a', 'b', 'c', 'd'].indexOf(k);
    if (idx >= 0) {
      e.preventDefault();
      select(S.items[S.idx].order[idx]);
    } else if (k === 'enter') {
      // Always the primary action, even when a button (e.g. Listen) still has focus. Space activates the focused button.
      e.preventDefault();
      const id = S.items[S.idx].id;
      if (S.practice && !S.checked[id]) { if (S.answers[id]) check(); }
      else if (S.idx < S.items.length - 1) go(S.idx + 1);
      else requestFinish();
    } else if (k === 'arrowright') { go(S.idx + 1); }
    else if (k === 'n') { if (S.idx < S.items.length - 1) go(S.idx + 1); else requestFinish(); }
    else if (k === 'arrowleft') { go(S.idx - 1); }
    else if (k === 'f') { toggleFlag(); }
    else if (k === 'l') { Narrator.clickListen(`q:${S.items[S.idx].id}`); }
    else if (k === 'e') { Narrator.clickListen(`x:${S.items[S.idx].id}`); }
    else if (k === 'r') { e.preventDefault(); Narrator.replay(`q:${S.items[S.idx].id}`); }
    else if (k === 'escape') { $('#navigator').hidden = true; }
  });

  $('#brand-home').addEventListener('click', () => {
    if (S && !$('#view-exam').hidden) { $('#dlg-exit').showModal(); return; }
    renderHome();
  });

  renderHome();
})();
